import{z as B,x as d,o as r,c as p,q as l,j as o,D as E,d as t,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"范式与分解","description":"","frontmatter":{"title":"范式与分解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/normal-forms.md","filePath":"cs/normal-forms.md","lastUpdated":1791413859000}'),A={name:"cs/normal-forms.md"};function F(m,a,D,h,N,f){const s=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="范式与分解" tabindex="-1">范式与分解 <a class="header-anchor" href="#范式与分解" aria-label="Permalink to &quot;范式与分解&quot;">​</a></h1><div class="epigraph"><p>异常来自把不同事实塞进同一关系；分解按函数依赖切开，连接再拼回。</p><footer>—— 据 Codd 对 3NF；Codd, Further Normalization, 1972；Bernstein 对合成算法的整理</footer></div><p><a href="/cs/predicate-pushdown">上一课</a>在查询树上做等价变换。本课不改某一条 SQL。缺口是：模式本身若把多个独立事实捆在一行，更新会出现插入、删除、修改异常。范式用函数依赖判断「这张表是否太宽」；分解给出更窄的关系，用连接恢复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/keys-integrity">键</a>已经能识别元组。若非主属性依赖键的真子集（部分依赖），或依赖其他非主属性（传递依赖），同一事实会重复出现，删一行可能丢掉无关事实。缺口不是新的查询语言，而是模式设计：1NF 禁止表中表；2NF 去掉部分依赖；3NF / BCNF 处理传递与键侧的依赖。</p><p><span class="marginnote">数字实例：表（学号，课程号，系名，系主任）的键是（学号，课程号）。但系名只由学号决定——半个键就够了，这就是部分依赖。同一学生选 5 门课，「系名＝数学系」就重复存 5 遍；一旦他转系，5 行里漏改 1 行，数据就自相矛盾。</span></p><p><span class="marginnote">术语翻译：函数依赖 \\(X \\to Y\\) 就是「知道 \\(X\\) 的值就能唯一确定 \\(Y\\) 的值」这一事实，如「学号 → 系名」：不会有两个同学号的人属不同系。闭包 \\(X^+\\) 则是「由 \\(X\\) 出发一路能推出所有属性」的清单。</span></p><p>本课不把「永远 BCNF」写成教条。有的依赖集无法既保依赖又保无损连接又落在 BCNF；3NF 合成是常用折中。</p><p><span class="marginnote">无损连接：分解后的自然连接能恢复原关系。依赖保持：原有函数依赖仍能在单个分解后的关系上检查，而不必先连接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定属性集 \\(U\\) 与函数依赖集 \\(F\\)。用闭包判断候选键。若违反目标范式，分解成投影，使每一投影满足范式，且分解无损。3NF 合成按 \\(F\\) 的正则覆盖建表；BCNF 分解沿违反依赖切开。本课不把多值依赖与 4NF 写进主干，只点名它们存在。</p>',11)),(r(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E5%87%BD%E6%95%B0%E4%BE%9D%E8%B5%96%20F%22%5D%20--%3E%20KEY%5B%22%E5%80%99%E9%80%89%E9%94%AE%22%5D%0A%20%20FD%20--%3E%20NF%5B%222NF%20%2F%203NF%20%2F%20BCNF%22%5D%0A%20%20NF%20--%3E%20DEC%5B%22%E6%97%A0%E6%8D%9F%E5%88%86%E8%A7%A3%22%5D%0A%20%20DEC%20--%3E%20VIEW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%A7%86%E5%9B%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"分解之后，更新局部化：改一处事实只碰一张表。查询则可能要多做连接——这正是前几课计划和代价要付的账。所以规范化是逻辑设计，不是「查询一定更快」。反规范化是故意保留冗余换少连接，完整性改由应用或触发器补；主干把这标成权衡，不标成另一套模型。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「范式越高查询越快」，实际上正好相反——分解后查全貌要多做连接，规范化保障的是更新不出矛盾，不是读性能。反规范化是明白代价后故意换速度，不是偷懒。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：反规范化像把同事的常用电话抄在自己笔记本上——打电话少翻通讯录（少一次连接），但对方换号时你得记得手动同步，忘了就出错。")],-1)),(r(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%96%E4%B8%80%E4%B8%AA%E9%9D%9E%E4%B8%BB%E5%B1%9E%E6%80%A7%20B%22%5D%20--%3E%20B%7B%22%E8%B0%81%E5%86%B3%E5%AE%9A%20B%3F%22%7D%0A%20%20B%20--%3E%7C%22%E9%94%AE%E7%9A%84%E7%9C%9F%E5%AD%90%E9%9B%86%22%7C%20C%5B%22%E9%83%A8%E5%88%86%E4%BE%9D%E8%B5%96%3A%20%E8%BF%9D%E5%8F%8D%202NF%22%5D%0A%20%20B%20--%3E%7C%22%E5%8F%A6%E4%B8%80%E4%B8%AA%E9%9D%9E%E4%B8%BB%E5%B1%9E%E6%80%A7%22%7C%20D%5B%22%E4%BC%A0%E9%80%92%E4%BE%9D%E8%B5%96%3A%20%E8%BF%9D%E5%8F%8D%203NF%22%5D%0A%20%20B%20--%3E%7C%22%E5%AE%8C%E6%95%B4%E5%80%99%E9%80%89%E9%94%AE%22%7C%20E%5B%22%E5%90%88%E8%A7%84%22%5D%0A%20%20C%20--%3E%20F%5B%22%E6%B2%BF%E8%AF%A5%E4%BE%9D%E8%B5%96%E6%8B%86%E8%A1%A8%22%5D%0A%20%20D%20--%3E%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><a href="/cs/relational-algebra">关系代数</a>的连接这时从「查询写法」变成「模式恢复」：分解的正确性条件就是那次连接无损。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ER 图作图法，不把范式当成文件分片。也不处理时态、XML、文档模型的「嵌套是否 1NF」。NULL 与弱实例理论不展开。后课视图可以让用户仍看见「宽表」，底下是分解后的关系。</p><p>依赖必须声明或从数据里发现；本课假定 \\(F\\) 已给定。后课默认：谈到基表，依赖已尽量收进 3NF/BCNF 权衡；宽行若出现，是显式反规范，不是没学过依赖。</p><p>分解后的模式仍是关系模型里的关系，只是更窄。查询变多连接，正是前几课计划要付的账，不是范式失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>改写动查询树；本课按函数依赖分解模式。</li><li>无损与保依赖是分解的正确性条件，不是审美。</li><li>视图如何挡住分解后的碎片，是后课缺口。</li><li>出处：Codd, 1972；Date；Ramakrishnan and Gehrke。</li></ul>',7))])}const c=B(A,[["render",F]]);export{u as __pageData,c as default};
